module SubsetCostSum(\n    input clk,\n    input rst_n,\n    input start,\n    input [31:0] N,\n    input [7:0] k,\n    output reg [31:0] result,\n    output reg done\n);\n    localparam [31:0] MOD = 32'd1000000007;\n    localparam [7:0] MAX_K = 8;\n    \n    // Precompute modular inverses for 1-8 (1/value mod MOD)\n    localparam [31:0] inv1 = 32'd1;\n    localparam [31:0] inv2 = 32'd500000004;\n    localparam [31:0] inv3 = 32'd333333336;\n    localparam [31:0] inv4 = 32'd250000002;\n    localparam [31:0] inv5 = 32'd400000003;\n    localparam [31:0] inv6 = 32'd166666668;\n    localparam [31:0] inv7 = 32'd142857144;\n    localparam [31:0] inv8 = 32'd125000001;\n    \n    // State machine declarations\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] INIT         = 4'd1;\n    localparam [3:0] STIRLING_DP  = 4'd2;\n    localparam [3:0] COMPUTE_FACT = 4'd3;\n    localparam [3:0] COMPUTE_COMB = 4'd4;\n    localparam [3:0] POW2_N       = 4'd5;\n    localparam [3:0] FINAL_SUM    = 4'd6;\n    localparam [3:0] DONE_STATE   = 4'd7;\n    \n    reg [3:0] state, next_state;\n    reg [31:0] dp [0:MAX_K];      // Stirling numbers (S2)\n    reg [31:0] fact [0:MAX_K];   // Factorials\n    reg [31:0] comb [0:MAX_K];   // Binomial coefficients\n    \n    // 2^N computation\n    reg [31:0] base_pow, pow2_N_result;\n    reg [31:0] exp_pow;\n    reg [5:0] exp_counter;       // Up to 32 cycles\n    \n    // Final sum computation\n    reg [31:0] pow2_N_i;\n    reg [31:0] final_sum;\n    reg [3:0] sum_counter;\n    \n    // Loop counters\n    reg [3:0] n_ptr, i_ptr;\n    \n    integer i;  // Integer for array initialization\n    \n    // Finite state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            \n            // Initialize arrays\n            for (i = 0; i <= MAX_K; i = i + 1) begin\n                dp[i] <= 32'd0;\n                fact[i] <= 32'd0;\n                comb[i] <= 32'd0;\n            end\n            \n            exp_counter <= 6'd0;\n            sum_counter <= 4'd0;\n            final_sum <= 32'd0;\n            n_ptr <= 4'd0;\n            i_ptr <= 4'd0;\n            \n            base_pow <= 32'd0;\n            exp_pow <= 32'd0;\n            pow2_N_result <= 32'd0;\n            pow2_N_i <= 32'd0;\n        end else begin\n            state <= next_state;\n            done <= 1'b0;  // Default done is 0\n            \n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        next_state <= INIT;\n                    end\n                end\n                \n                INIT: begin\n                    // Initialize Stirling dp array\n                    dp[0] <= 32'd1;\n                    for (i = 1; i <= MAX_K; i = i + 1) begin\n                        dp[i] <= 32'd0;\n                    end\n                    n_ptr <= 4'd1;  // Start n=1\n                    i_ptr <= 4'd1;  // Start i=1\n                    fact[0] <= 32'd1;\n                    comb[0] <= 32'd1;\n                    \n                    next_state <= STIRLING_DP;\n                end\n                \n                STIRLING_DP: begin\n                    if (n_ptr > k) begin\n                        next_state <= COMPUTE_FACT;\n                    end else begin\n                        if (i_ptr <= n_ptr) begin\n                            // dp[i] = (i * dp[i] + dp[i-1]) % MOD;\n                            dp[i_ptr] <= ((i_ptr * dp[i_ptr]) % MOD + dp[i_ptr - 1]) % MOD;\n                            i_ptr <= i_ptr + 4'd1;\n                        end else begin\n                            n_ptr <= n_ptr + 4'd1;\n                            i_ptr <= 4'd1;\n                        end\n                    end\n                end\n                \n                COMPUTE_FACT: begin\n                    if (i_ptr <= k) begin\n                        fact[i_ptr] <= (fact[i_ptr - 1] * i_ptr) % MOD;\n                        i_ptr <= i_ptr + 4'd1;\n                    end else begin\n                        i_ptr <= 4'd1;  // Prepare comb/I loop\n                        next_state <= COMPUTE_COMB;\n                    end\n                end\n                \n                COMPUTE_COMB: begin\n                    if (i_ptr <= k) begin\n                        // comb[i] = comb[i-1] * (N - i_ptr + 1) * inv[i_ptr] % MOD\n                        comb[i_ptr] <= (comb[i_ptr - 1] * ((N - i_ptr + 1) % MOD) % MOD) * inv_selector(i_ptr) % MOD;\n                        i_ptr <= i_ptr + 4'd1;\n                    end else begin\n                        next_state <= POW2_N;\n                        base_pow <= 32'd2;\n                        pow2_N_result <= 32'd1;\n                        exp_pow <= N;\n                        exp_counter <= 6'd0;\n                    end\n                end\n                \n                POW2_N: begin\n                    if (exp_counter < 6'd32) begin\n                        if (exp_pow[0]) begin\n                            pow2_N_result <= (pow2_N_result * base_pow) % MOD;\n                        end\n                        base_pow <= (base_pow * base_pow) % MOD;\n                        exp_pow <= exp_pow >> 1;\n                        exp_counter <= exp_counter + 6'd1;\n                    end else begin\n                        pow2_N_i <= pow2_N_result;\n                        sum_counter <= 4'd1; // Start at i=1\n                        final_sum <= 32'd0;\n                        next_state <= FINAL_SUM;\n                    end\n                end\n                \n                FINAL_SUM: begin\n                    if (sum_counter <= k) begin\n                        // term = dp[i] * fact[i] * comb[i] * pow2_N_i mod MOD\n                        final_sum <= (final_sum + (dp[sum_counter] * fact[sum_counter] % MOD * comb[sum_counter] % MOD * pow2_N_i % MOD)) % MOD;\n                        pow2_N_i <= (pow2_N_i * 32'd500000004) % MOD; // Multiply by 1/2 mod MOD\n                        sum_counter <= sum_counter + 4'd1;\n                    end else begin\n                        result <= final_sum;\n                        next_state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\n    // Inversion selector\n    function [31:0] inv_selector;\n        input [3:0] x;\n        case (x)\n            4'd1: inv_selector = inv1;\n            4'd2: inv_selector = inv2;\n            4'd3: inv_selector = inv3;\n            4'd4: inv_selector = inv4;\n            4'd5: inv_selector = inv5;\n            4'd6: inv_selector = inv6;\n            4'd7: inv_selector = inv7;\n            4'd8: inv_selector = inv8;\n            default: inv_selector = 32'd1;\n        endcase\n    endfunction\n\nendmodule